static void smartlightsystem_eventqueue_init(smartlightsystem_eventqueue * eq, smartlightsystem_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer smartlightsystem_eventqueue_size(smartlightsystem_eventqueue * eq)
{
	return eq->size;
}

static smartlightsystem_event smartlightsystem_eventqueue_pop(smartlightsystem_eventqueue * eq)
{
	smartlightsystem_event event;
	if(smartlightsystem_eventqueue_size(eq) <= 0) {
		smartlightsystem_event_init(&event, SmartLightSystem_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean smartlightsystem_eventqueue_push(smartlightsystem_eventqueue * eq, smartlightsystem_event ev)
{
	if(smartlightsystem_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void smartlightsystem_event_init(smartlightsystem_event * ev, SmartLightSystemEventID name)
{
	ev->name = name;
}

static void smartLightSystem_add_event_to_queue(smartlightsystem_eventqueue * eq, SmartLightSystemEventID name)
{
	smartlightsystem_event event;
	smartlightsystem_event_init(&event, name);
	smartlightsystem_eventqueue_push(eq, event);
}

